$\mathcal{M}_\text{pruned} \gets \text{Remove}(\mathcal{M}, \mathcal{P})$\;
\BlankLine
\tcc{Stage 3: RLVR Recovery}
$\mathcal{M}' \gets \text{GRPO}(\mathcal{M}_\text{pruned}, \mathcal{D}_\text{rec})$\;
\Return{$\mathcal{M}'$}
